UPDATE public.pages SET builder_data = $builder${"version": 1, "sections": [{"id": "8ac19ffd-86f5-4d3e-9c07-b08340343b6d", "kind": "section", "layout": {"width": 1200, "contentWidth": "boxed"}, "children": [{"id": "81483a6f-ef79-4ddf-b752-69724f66d9ff", "kind": "column", "span": {"desktop": 12}, "children": [{"id": "27cf22c4-bb45-4139-8684-10359d21fc5e", "kind": "widget", "type": "heading", "content": {"tag": "h1", "text_pl": "Reklamuj się z nami", "text_en": "Advertise with us", "variant": "default", "sizePreset": "display"}}, {"id": "bfb912f2-6e6f-4f88-a5b2-3c80b4a10db7", "kind": "widget", "type": "text", "content": {"html_pl": "<p><strong>Twój sukces zaczyna się tutaj:</strong></p><p>efektywność KPI w zaufanym, skalowalnym środowisku</p><p>Twoja kampania zasługuje na najlepsze - nasze rozwiązania premium to sposób na osiągnięcie wyznaczonych celów.</p>", "html_en": "<p><strong>Your success starts here:</strong></p><p>KPI performance in a trusted, scalable environment</p><p>Your campaign deserves the best - our premium solutions are the way to achieve your goals.</p>"}}, {"id": "cdca27d5-f2bc-4ba6-bd2c-98acef1a7448", "kind": "widget", "type": "heading", "content": {"tag": "h2", "text_pl": "Poznaj naszą ofertę", "text_en": "Explore our offer", "variant": "default", "sizePreset": "xl"}}]}]}, {"id": "49a9a56c-965e-44fc-8eb4-59eb0f40e6a1", "kind": "section", "layout": {"width": 1200, "contentWidth": "boxed"}, "children": [{"id": "d2cad0a2-7e2c-44a3-accd-d10a30971fe3", "kind": "column", "span": {"desktop": 12}, "children": [{"id": "67d598eb-6905-434e-8c77-007b4d6cc5d0", "kind": "widget", "type": "heading", "content": {"tag": "h2", "text_pl": "Reklamy natywne", "text_en": "Native ads", "variant": "default", "sizePreset": "xl"}}, {"id": "9be4c6e0-1401-4745-a3ef-5f10734c8dff", "kind": "widget", "type": "tabs", "content": {"tabs": [{"label_pl": "Reklamy wkomponowane", "label_en": "In-content ads", "html_pl": "<p><strong>Wymiary (w pikselach):</strong> 300×200 (obraz miniatury)</p><p><strong>Format pliku:</strong> JPG/PNG, maksymalnie 50 KB</p><p><strong>Animacje/Wideo:</strong> Niedozwolone</p><p><strong>Nagłówek:</strong> Maksymalnie 25 znaków (z uwzględnieniem spacji)</p><p><strong>Opis:</strong> Maksymalnie 100 znaków (z uwzględnieniem spacji)</p><p><strong>URL przekierowania:</strong> Wymagany</p><p><strong>Nazwa reklamodawcy:</strong> Tekst</p><p><strong>Komunikat CTA:</strong> Maksymalnie 15 znaków</p><p><strong>Uwagi:</strong> W przesłanym obrazie nie mogą znajdować się teksty ani logotypy.</p><h4>Dodatkowe informacje</h4><p><strong>- Akceptowane pliki:</strong> JPG lub PNG do 50 KB.</p><p><strong>- URL przekierowania:</strong> Wymagany; opcjonalne zewnętrzne systemy śledzenia.</p><p><strong>- Strony docelowe:</strong> Reklama powinna kierować do stron z treścią (np. artykułów, materiałów edukacyjnych), a nie stron promujących produkt lub usługę.</p><p><img src=\"https://unnltowbgszpdzwpawdu.supabase.co/storage/v1/object/public/media/07167e87-2e0f-42e8-ac5e-72445a2d4b0a/wp-import/2026/59a7c852f464c06a61163b4e0b9d6b58e51381a83543831286e238e009ceca33.png\" alt=\"Reklamy wkomponowane\" style=\"width:100%;height:auto;border-radius:8px;margin-top:16px\" /></p>", "html_en": "<p><strong>Dimensions (px):</strong> 300×200 (thumbnail image)</p><p><strong>File format:</strong> JPG/PNG, max 50 KB</p><p><strong>Animation/Video:</strong> Not allowed</p><p><strong>Headline:</strong> Max 25 characters (including spaces)</p><p><strong>Description:</strong> Max 100 characters (including spaces)</p><p><strong>Redirect URL:</strong> Required</p><p><strong>Advertiser name:</strong> Text</p><p><strong>CTA message:</strong> Max 15 characters</p><p><strong>Notes:</strong> Submitted image must not contain text or logos.</p><h4>Additional info</h4><p><strong>- Accepted files:</strong> JPG or PNG up to 50 KB.</p><p><strong>- Redirect URL:</strong> Required; optional third-party tracking.</p><p><strong>- Landing pages:</strong> Ads should link to content pages (e.g. articles, educational materials), not product/service promotion pages.</p><p><img src=\"https://unnltowbgszpdzwpawdu.supabase.co/storage/v1/object/public/media/07167e87-2e0f-42e8-ac5e-72445a2d4b0a/wp-import/2026/59a7c852f464c06a61163b4e0b9d6b58e51381a83543831286e238e009ceca33.png\" alt=\"Reklamy wkomponowane\" style=\"width:100%;height:auto;border-radius:8px;margin-top:16px\" /></p>"}, {"label_pl": "Wideo natywne", "label_en": "Native video", "html_pl": "<p><strong>Wymiary (w pikselach):</strong> 1280×720</p><p><strong>Format pliku:</strong> MP4, maksymalnie 2.5 MB / 5 MB</p><p><strong>Długość animacji/wideo:</strong> Preferowane maksymalnie 15 sekund; dopuszczalne do 30 sekund</p><p><strong>Uwagi:</strong> Vast Tag jest akceptowalny</p><h4>Dodatkowe informacje</h4><p><strong>- Akceptowane pliki:</strong> JPEG lub PNG do 50 KB.</p><p><strong>- URL przekierowania:</strong> Wymagany; opcjonalne zewnętrzne systemy śledzenia.</p><p><strong>- Zawartość obrazu:</strong> W przesłanych materiałach nie mogą znajdować się teksty ani logotypy.</p><p><img src=\"https://unnltowbgszpdzwpawdu.supabase.co/storage/v1/object/public/media/07167e87-2e0f-42e8-ac5e-72445a2d4b0a/wp-import/2026/c93804c539f3bd5c299caedd831b72fac81685ae3339264d7d8d8547d0090180.webp\" alt=\"Wideo natywne\" style=\"width:100%;height:auto;border-radius:8px;margin-top:16px\" /></p>", "html_en": "<p><strong>Dimensions (px):</strong> 1280×720</p><p><strong>File format:</strong> MP4, max 2.5 MB / 5 MB</p><p><strong>Animation/video length:</strong> Preferred max 15 seconds; up to 30 seconds allowed</p><p><strong>Notes:</strong> VAST Tag accepted</p><h4>Additional info</h4><p><strong>- Accepted files:</strong> JPEG or PNG up to 50 KB.</p><p><strong>- Redirect URL:</strong> Required; optional third-party tracking.</p><p><strong>- Image content:</strong> Submitted materials must not contain text or logos.</p><p><img src=\"https://unnltowbgszpdzwpawdu.supabase.co/storage/v1/object/public/media/07167e87-2e0f-42e8-ac5e-72445a2d4b0a/wp-import/2026/c93804c539f3bd5c299caedd831b72fac81685ae3339264d7d8d8547d0090180.webp\" alt=\"Wideo natywne\" style=\"width:100%;height:auto;border-radius:8px;margin-top:16px\" /></p>"}]}}]}]}, {"id": "54919ddb-bba2-4f61-9e38-4fa6e8c7f752", "kind": "section", "layout": {"width": 1200, "contentWidth": "boxed"}, "children": [{"id": "11148593-0b2d-46b4-b6be-cef5ff3e0ff5", "kind": "column", "span": {"desktop": 12}, "children": [{"id": "3c8487e0-6ca3-4943-b6d2-1415a2114660", "kind": "widget", "type": "heading", "content": {"tag": "h2", "text_pl": "Personalizowane materiały reklamowe wewnętrznej produkcji", "text_en": "Custom in-house creatives", "variant": "default", "sizePreset": "xl"}}, {"id": "c4d0b80f-e60a-464a-85be-2a93986c7505", "kind": "widget", "type": "tabs", "content": {"tabs": [{"label_pl": "Reklama graficzna osadzona w artykule", "label_en": "Graphic ad in article", "html_pl": "<p><strong>Wymiary (w pikselach):</strong> 100% VW × 375px, szerokość między 300 a 708 px</p><p><strong>Format pliku:</strong> HTML do 1.5 MB / HTML + 1 wideo MP4/MOV do 5 MB</p><p><strong>Czas animacji/wideo:</strong> Maksymalnie 15 sekund, 24 FPS</p><p><strong>Nagłówek:</strong> Maksymalnie 25 znaków</p><p><strong>Opis:</strong> Maksymalnie 100 znaków</p><p><strong>URL przekierowania:</strong> Wymagany</p><p><strong>Logo reklamodawcy:</strong> 1 logo (opcjonalnie), format EPS</p><p><strong>Komunikat CTA:</strong> Maksymalnie 15 znaków</p><p><strong>Zewnętrzne systemy śledzenia:</strong> Do 2 (impresje i kliknięcia)</p><h4>Dodatkowe informacje</h4><p><strong>- Początkowe ładowanie:</strong> Maksymalnie 300 KB</p><p><strong>- Rozszerzenia:</strong> Niedozwolone</p><p><strong>- Białe reklamy:</strong> Muszą posiadać widoczną ramkę o grubości min. 1 px (zalecany #CCC).</p><p><strong>- Wytyczne:</strong> Reklamodawca musi dostarczyć wytyczne marki oraz czcionki w formacie OTF/WOFF2.</p><p><strong>- Wideo i animacje:</strong> Ograniczone do 15 sekund.</p><p><strong>- Reklama wideo w banerze:</strong> Dopuszczalna; autoodtwarzanie możliwe, dźwięk domyślnie wyciszony.</p><p><img src=\"https://unnltowbgszpdzwpawdu.supabase.co/storage/v1/object/public/media/07167e87-2e0f-42e8-ac5e-72445a2d4b0a/wp-import/2026/cbad82baad990fd4425880fe4f7b8eb77f108765ad3e60a92621f83610ed81b0.png\" alt=\"Reklama graficzna osadzona w artykule\" style=\"width:100%;height:auto;border-radius:8px;margin-top:16px\" /></p>", "html_en": "<p><strong>Dimensions (px):</strong> 100% VW × 375px, width 300-708 px</p><p><strong>File format:</strong> HTML up to 1.5 MB / HTML + 1 MP4/MOV video up to 5 MB</p><p><strong>Animation/video duration:</strong> Max 15 seconds, 24 FPS</p><p><strong>Headline:</strong> Max 25 characters</p><p><strong>Description:</strong> Max 100 characters</p><p><strong>Redirect URL:</strong> Required</p><p><strong>Advertiser logo:</strong> 1 logo (optional), EPS format</p><p><strong>CTA message:</strong> Max 15 characters</p><p><strong>Third-party tracking:</strong> Up to 2 (impressions and clicks)</p><h4>Additional info</h4><p><strong>- Initial load:</strong> Max 300 KB</p><p><strong>- Expansions:</strong> Not allowed</p><p><strong>- White ads:</strong> Must have a visible border of at least 1px (recommended #CCC).</p><p><strong>- Guidelines:</strong> Advertiser must supply brand guidelines and fonts in OTF/WOFF2.</p><p><strong>- Video/animation:</strong> Limited to 15 seconds.</p><p><strong>- In-banner video:</strong> Allowed; autoplay ok, sound muted by default.</p><p><img src=\"https://unnltowbgszpdzwpawdu.supabase.co/storage/v1/object/public/media/07167e87-2e0f-42e8-ac5e-72445a2d4b0a/wp-import/2026/cbad82baad990fd4425880fe4f7b8eb77f108765ad3e60a92621f83610ed81b0.png\" alt=\"Reklama graficzna osadzona w artykule\" style=\"width:100%;height:auto;border-radius:8px;margin-top:16px\" /></p>"}, {"label_pl": "Reklama wideo osadzona w artykule", "label_en": "Video ad in article", "html_pl": "<p><strong>Wymiary (w pikselach):</strong> 16:9 WIDESCREEN, 1280×720, 720p</p><p><strong>Format pliku:</strong> MP4, maksymalnie 5 MB</p><p><strong>Czas animacji/wideo:</strong> Maksymalnie 15 sekund (preferowane) lub 30 sekund, 24 FPS</p><p><strong>URL przekierowania:</strong> Wymagany</p><p><strong>Uwagi:</strong> Autoodtwarzanie jest dozwolone</p><h4>Dodatkowe informacje</h4><p><strong>- Wytyczne marki:</strong> Reklamodawca dostarcza wytyczne marki oraz czcionki OTF/WOFF2.</p><p><strong>- Wideo i animacje:</strong> Ograniczone do 15 sekund.</p><p><strong>- Reklama wideo w banerze:</strong> Dozwolona, autoodtwarzanie możliwe, dźwięk domyślnie wyciszony.</p><p><img src=\"https://unnltowbgszpdzwpawdu.supabase.co/storage/v1/object/public/media/07167e87-2e0f-42e8-ac5e-72445a2d4b0a/wp-import/2026/c93804c539f3bd5c299caedd831b72fac81685ae3339264d7d8d8547d0090180.webp\" alt=\"Wideo natywne\" style=\"width:100%;height:auto;border-radius:8px;margin-top:16px\" /></p>", "html_en": "<p><strong>Dimensions (px):</strong> 16:9 WIDESCREEN, 1280×720, 720p</p><p><strong>File format:</strong> MP4, max 5 MB</p><p><strong>Animation/video duration:</strong> Max 15s (preferred) or 30s, 24 FPS</p><p><strong>Redirect URL:</strong> Required</p><p><strong>Notes:</strong> Autoplay allowed</p><h4>Additional info</h4><p><strong>- Brand guidelines:</strong> Advertiser supplies brand guidelines and OTF/WOFF2 fonts.</p><p><strong>- Video/animation:</strong> Limited to 15 seconds.</p><p><strong>- In-banner video:</strong> Allowed; autoplay possible, sound muted by default.</p><p><img src=\"https://unnltowbgszpdzwpawdu.supabase.co/storage/v1/object/public/media/07167e87-2e0f-42e8-ac5e-72445a2d4b0a/wp-import/2026/c93804c539f3bd5c299caedd831b72fac81685ae3339264d7d8d8547d0090180.webp\" alt=\"Wideo natywne\" style=\"width:100%;height:auto;border-radius:8px;margin-top:16px\" /></p>"}]}}]}]}, {"id": "048c1ac2-fbcf-46b2-acfb-3a7a49cf043c", "kind": "section", "layout": {"width": 1200, "contentWidth": "boxed"}, "children": [{"id": "0dd9be86-ab63-4177-8749-5ae11e2